import{_ as s,o as e,c as p,a2 as t}from"./chunks/framework.EUByU7Iq.js";const d=JSON.parse('{"title":"八月十五夜赠张功曹","description":"","frontmatter":{"title":"八月十五夜赠张功曹","date":"2026-11-23T00:00:00.000Z","seq":27,"categories":["美文","唐诗三百首"],"collection":"《唐诗三百首 · 七言古诗》","tags":["唐诗三百首","唐"],"poem":true,"poem_quote":false,"author":"韩愈","source_book":"唐诗三百首"},"headers":[],"relativePath":"blogs/唐诗三百首·七言古诗/八月十五夜赠张功曹.md","filePath":"blogs/唐诗三百首·七言古诗/八月十五夜赠张功曹.md"}'),o={name:"blogs/唐诗三百首·七言古诗/八月十五夜赠张功曹.md"};function l(c,a,n,_,m,r){return e(),p("div",null,[...a[0]||(a[0]=[t('<h1 id="八月十五夜赠张功曹" tabindex="-1">八月十五夜赠张功曹 <a class="header-anchor" href="#八月十五夜赠张功曹" aria-label="Permalink to &quot;八月十五夜赠张功曹&quot;">​</a></h1><p class="poem-meta">唐 · 韩愈　·　七言古诗</p><div class="poem"><p class="poem-stanza">纤云四卷天无河，清风吹空月舒波。</p><p class="poem-stanza">沙平水息声影绝，一杯相属君当歌。</p><p class="poem-stanza">君歌声酸辞且苦，不能听终泪如雨。</p><p class="poem-stanza">洞庭连天九疑高，蛟龙出没猩鼯号。</p><p class="poem-stanza">十生九死到官所，幽居默默如藏逃。</p><p class="poem-stanza">下床畏蛇食畏药，海气湿蛰薰腥臊。</p><p class="poem-stanza">昨者州前捶大鼓，嗣皇继圣登夔皋。</p><p class="poem-stanza">赦书一日行万里，罪从大辟皆除死。</p><p class="poem-stanza">迁者追回流者还，涤瑕荡垢清朝班。</p><p class="poem-stanza">州家申名使家抑，坎轲只得移荆蛮。</p><p class="poem-stanza">判司卑官不堪说，未免捶楚尘埃间。</p><p class="poem-stanza">同时辈流多上道，天路幽险难追攀。</p><p class="poem-stanza">君歌且休听我歌，我歌今与君殊科。</p><p class="poem-stanza">一年明月今宵多，人生由命非由他。</p><p class="poem-stanza">有酒不饮奈明何。</p></div>',3)])])}const z=s(o,[["render",l]]);export{d as __pageData,z as default};
